using System;
using System.IO;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
namespace CampaignDemo.Editor
{
    public static class FortBreachVerification
    {
        static readonly List<string> results=new List<string>();
        static void Check(bool value,string name){if(!value)throw new Exception(name);results.Add("PASS "+name);}
        static void Near(float a,float b,string name){Check(Mathf.Abs(a-b)<.01f,name+" actual="+a);}
        public static void Configure(){FortNodeInstaller.Configure();var c=UnityEngine.Object.FindObjectOfType<CampaignRuntime>();EditorUtility.SetDirty(c.combined.engineering);AssetDatabase.SaveAssets();}
        public static void Run(){try{Configure();Validate();EditorApplication.Exit(0);}catch(Exception e){File.WriteAllText("fort-breach-verification.txt",e+"\n"+string.Join("\n",results));Debug.LogException(e);EditorApplication.Exit(1);}}
        public static void Validate()
        {
            results.Clear();var root=new GameObject("Breach tests");var w=root.AddComponent<BattleWorld>();w.enabled=false;w.players=new[]{"A","B"};w.currentPlayer="A";w.points=new RecoveryPoint[0];w.fogEnabled=false;var c=root.AddComponent<CampaignRuntime>();c.enabled=false;c.world=w;c.rules=ScriptableObject.CreateInstance<CampaignRules>();c.combined=root.AddComponent<CombinedArmsWorld>();c.combined.enabled=false;c.combined.world=w;c.combined.engineering=ScriptableObject.CreateInstance<EngineeringDefinition>();c.combined.engineering.metersPerWorldUnit=10;c.combined.engineering.lineDismantleSecondsPerMeter=1;c.logistics=root.AddComponent<LogisticsWorld>();c.logistics.enabled=false;c.logistics.world=w;c.Bind();w.campaign=c;
            var map=root.AddComponent<FreeMarchMapRuntime>();map.definition=ScriptableObject.CreateInstance<FreeMarchMapDefinition>();map.definition.bounds=new Rect(-5,-5,10,10);var setup=root.AddComponent<RoadMarchSceneSetup>();setup.freeMarchMap=map;w.setup=setup;var g=new GameObject("engineer");g.transform.SetParent(root.transform);g.transform.position=new Vector3(0,1);var worker=g.AddComponent<BattleUnit>();worker.unitId="worker";worker.ownerId="A";worker.combatDefinition=ScriptableObject.CreateInstance<ArmyCombatDefinition>();worker.combatDefinition.role=UnitRole.Engineer;worker.combatDefinition.echelon=ArmyEchelon.Squad;worker.combatDefinition.visionRadius=4;var road=g.AddComponent<ArmyRoadMover>();road.definition=ScriptableObject.CreateInstance<ArmyDefinition>();var motor=g.AddComponent<ArmyRouteMotor>();motor.Initialize(RoadRouteView.Create(g.transform,"route",.02f,1,Color.blue));var free=g.AddComponent<ArmyFreeMarchMover>();free.allowedTerrain=TerrainAccess.Ground|TerrainAccess.Grass|TerrainAccess.Road;free.Initialize(motor);free.BindMap(map);c.ConfigureUnit(worker);w.units=new[]{worker};w.Initialize();
            var fort=c.lineWorks.CreateLine(new[]{new Vector3(-2,0),new Vector3(0,0),new Vector3(2,0)},Vector3.up,"B",1,40);fort.Damage(fort.Health*.25f);var draw=new[]{new Vector3(-.5f,.1f),new Vector3(.5f,.1f)};
            Check(c.lineWorks.PlanBreach(worker,draw,out var plan,out _),"near-line drawing projects onto one enemy fort");Near(plan.lengthMeters,10,"effective demolition length uses target arclength");Near(plan.time,10,"enemy full dismantle time");Near(plan.site.y,0,"site from effective section midpoint");Check(!plan.own,"enemy target classification");
            fort.ownerId="A";Check(c.lineWorks.PlanBreach(worker,draw,out var own,out _),"same interaction works on own fort");Near(own.time,5,"own line time factor one half");fort.ownerId="B";
            Check(!c.lineWorks.PlanBreach(worker,new[]{new Vector3(-.5f,1),new Vector3(.5f,1)},out _,out _),"far drawing is invalid");Check(!c.lineWorks.PlanBreach(worker,new[]{new Vector3(-.5f,0),new Vector3(.5f,0),new Vector3(-.5f,0)},out _,out _),"backtracking cannot inflate effective section");
            Check(c.lineWorks.DismantleSection(worker,draw).accepted,"engineer accepts enemy section task");Check(c.lineWorks.Approaching(worker)&&motor.IsMoving,"worker automatically approaches section site");c.lineWorks.Tick(2);Near(c.lineWorks.Remaining(worker),10,"travel does not consume demolition time");motor.Stop();worker.transform.position=plan.site;c.lineWorks.Tick(0);Check(worker.Working,"arrival starts demolition work");c.lineWorks.Tick(5);Check(!fort.Destroyed&&fort.DistanceTo(Vector3.zero)==0,"no partial opening before task completes");c.lineWorks.Cancel(worker);Check(!fort.Destroyed,"cancel preserves original geometry");
            worker.transform.position=Vector3.zero;Check(c.lineWorks.DismantleSection(worker,draw).accepted,"restart section demolition");float originalHealth=fort.Health,originalMax=fort.MaximumHealth;c.lineWorks.Tick(10);Check(fort.Destroyed,"original replaced only at completion");var live=c.combined.fortifications.FindAll(f=>f!=null&&!f.Destroyed);Check(live.Count==2,"middle cut leaves two independent remaining fragments");float length=0,health=0,max=0;foreach(var f in live){length+=f.builtLengthMeters;health+=f.Health;max+=f.MaximumHealth;Check(f.ownerId=="B"&&f.level==1,"fragment retains original ownership and level");Check(f.lineGroupId==fort.lineGroupId,"fragments retain construction group");Check(f.DistanceTo(Vector3.zero)>=.49f,"removed section absent from all remaining geometry");}Near(length,30,"remaining total length exact");Near(health,originalHealth*.75f,"split does not heal damaged fort");Near(max,originalMax*.75f,"remaining max health proportional to length");Check(!live[0].Crosses(new Vector3(0,-1),new Vector3(0,1))&&!live[1].Crosses(new Vector3(0,-1),new Vector3(0,1)),"gap no longer has original crossing geometry");
            Check(!c.lineWorks.ToggleAutomaticRemoval("B",live[0]).accepted,"old remote deletion entry disabled");worker.combatDefinition.role=UnitRole.Infantry;Check(!c.lineWorks.DismantleSection(worker,new[]{new Vector3(-1.5f,0),new Vector3(-1,0)}).accepted,"only engineers can issue section task");worker.combatDefinition.role=UnitRole.Engineer;
            var fragment=live[0];var edgeDraw=new[]{fragment.linePoints[0],Vector3.Lerp(fragment.linePoints[0],fragment.linePoints[fragment.linePoints.Length-1],.5f)};Check(c.lineWorks.PlanBreach(worker,edgeDraw,out var edge,out _),"remaining fragment may be cut again");var leftovers=c.lineWorks.OpenBreach(fragment,edge.from,edge.to);Check(leftovers.Count==1,"end cut leaves one fragment");
            foreach(var f in c.combined.fortifications)if(f!=null)UnityEngine.Object.DestroyImmediate(f.gameObject);UnityEngine.Object.DestroyImmediate(root);File.WriteAllText("fort-breach-verification.txt",results.Count+" checks passed\n"+string.Join("\n",results));Debug.Log("FORT_BREACH_VERIFY_PASS "+results.Count);
        }
    }
}
